async page => {
 const reports=[];
 for(const [role,id] of [['leader','01a147d4-46ba-7243-aa30-4139bdbdd3ba'],['partner','01a147d6-1ab3-7504-8afe-a6ffc72d92e0']]) {
  const info=await page.evaluate(async id=>{const {aM:http}=await import('/registry/static/js/index-BBS9pLLM.js'); const r=await http.request('get','https://wt.ioa.pub/registry-server/api/v1/agent/client/'+id);const d=r.data||r;return {aic:d.aic,status:d.approval_status,active:d.is_active,comments:d.process_comments};},id);
  if(info.status!=='APPROVED'||!info.aic||!info.active){reports.push({role,...info,downloaded:false});continue;}
  const metadata=await page.evaluate(async ({aic,role})=>{
   const {aM:http}=await import('/registry/static/js/index-BBS9pLLM.js');
   const r=await http.request('post','https://wt.ioa.pub/registry-server/acps-atr-v2/eab/'+encodeURIComponent(aic));
   const e=r.data||r;
   if(!e.keyId||!e.macKey||e.aic!==aic)throw new Error('EAB response fields do not match the requested identity');
   const el=document.createElement('a');el.id='codex-owner-eab-download';el.download=role+'-eab.json';el.textContent='Download identity EAB';el.href=URL.createObjectURL(new Blob([JSON.stringify(e,null,2)],{type:'application/json'}));document.body.appendChild(el);
   return {aic,fields:Object.keys(e)};
  },{aic:info.aic,role});
  const event=page.waitForEvent('download',{timeout:15000});
  await page.locator('#codex-owner-eab-download').click();
  const download=await event;
  await download.saveAs('D:/AI + 开源/incident-pilot/integration/private/two-agent/'+role+'-eab.json');
  await page.evaluate(()=>{const e=document.querySelector('#codex-owner-eab-download');if(e){URL.revokeObjectURL(e.href);e.remove();}});
  reports.push({role,aic:info.aic,downloaded:true,fields:metadata.fields});
 }
 return {observed_at:new Date().toISOString(),identities:reports};
}
